#!/usr/bin/env python3
"""Build roqsim's Interbotix X-Series arm MJCFs from MuJoCo Menagerie's ``trossen_*`` models.

Two arms, one generator: the **ViperX 300 6DOF** (``vx300s``) and the **WidowX 250 6DOF**
(``wx250s``). They share a joint set, an actuator set and a gripper mechanism, so the second costs
almost nothing once the first is right.

Provenance is unusually direct. Trossen Robotics *is* Interbotix, and Menagerie's models are derived
from exactly the ``interbotix_xsarm_descriptions`` xacro the platform survey ranked -- so this takes
the curated MJCF path (as the xArm did) rather than expanding the xacro ourselves (as the ROSbot had
to). Every mass, inertia, joint limit, actuator gain, coupling and contact parameter is upstream's,
passed through unchanged.

Two deltas, both roqsim conventions:

1. **No ``<option>``.** Upstream pins ``cone="elliptic" impratio="10"``. Those are not incidental --
   they are the contact settings a *grasping* arm needs, and ``references/gripper.md`` opens with
   them. But they are world-scoped: a model carrying them reconfigures the contact solver for every
   other robot in the scene. Both already exist as ``sim.cone`` and ``sim.impratio``, so the demo
   world sets them (with ``sim.noslip_iterations``, which the architecture doc measures at a 137x
   reduction in grasp creep). The manifest says so too, because an arm whose gripper quietly creeps
   is the failure this avoids.
2. **``meshdir``/``texturedir`` point at ``meshes/``**, the package layout.

**The gripper is kept**, unlike the xArm's. On an X-Series arm the gripper is part of the platform
rather than a separate SKU: it is one ``position`` actuator on ``left_finger``, with ``right_finger``
mirrored through an ``<equality polycoef="0 -1 0 0 0">``. That makes it a *joint* actuator, not the
tendon ``arm_controller`` infers a gripper from -- so the manifest names it explicitly via
``joints:`` + ``gripper_actuator:``, which ``named_actuators`` resolves by actuator name.

Usage::

    python external/convert/build_interbotix_mjcf.py           # fetch and write both arms
    python external/convert/build_interbotix_mjcf.py --check   # rebuild and diff
"""

from __future__ import annotations

import argparse
import shutil
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from sources import resolve_source  # noqa: E402

MENAGERIE_URL = "https://github.com/google-deepmind/mujoco_menagerie.git"
MENAGERIE_COMMIT = "da76818e269b82289eba39808e2fb91d679d6994"

ROOT = Path(__file__).resolve().parents[2]
PKG = ROOT / "roqsim_manipulation_assets/src/roqsim_manipulation_assets/models"

#: model short name -> (Menagerie directory, human name)
ARMS = {
    "vx300s": ("trossen_vx300s", "ViperX 300 6DOF"),
    "wx250s": ("trossen_wx250s", "WidowX 250 6DOF"),
}

HEADER = """<mujoco model="{model}">
  <!--
    Interbotix/Trossen {human} ({model}) for MuJoCo.

    GENERATED by external/convert/build_interbotix_mjcf.py from MuJoCo Menagerie's
    `{subdir}` @ {commit} (BSD-3-Clause, Copyright 2023 Trossen Robotics -
    see {upper}_LICENSE). Do not hand-edit: re-run the generator. Every mass, inertia, joint
    limit, actuator gain, finger coupling and contact parameter below is upstream's own value.

    Upstream derives this from the same interbotix_xsarm_descriptions xacro the ROS 2 package
    ships, so the provenance chain back to the vendor is direct.

    The gripper is PART OF THE ARM here, unlike xarm7's: one position actuator on `left_finger`
    with `right_finger` mirrored by an <equality>. Because that is a JOINT actuator rather than a
    tendon, arm_controller cannot infer it - the manifest names it through joints: +
    gripper_actuator:.

    Two documented deltas:
      1. no <option> - upstream pins cone="elliptic" impratio="10", which are exactly the contact
         settings a grasping arm needs, but they are world-scoped. The demo world sets sim.cone,
         sim.impratio and sim.noslip_iterations; a grasping world MUST do the same or the grip
         creeps (see roqsim/docs/architecture.rst).
      2. meshdir/texturedir point at meshes/, this package's layout.
  -->
"""


def build(source: Path, model: str, subdir: str, human: str) -> str:
    tree = ET.parse(source / f"{model}.xml")
    root = tree.getroot()
    compiler = root.find("compiler")
    compiler.set("meshdir", "meshes")
    compiler.set("texturedir", "meshes")
    for option in root.findall("option"):
        root.remove(option)
    ET.indent(tree, space="  ")
    xml = ET.tostring(root, encoding="unicode")
    head = HEADER.format(model=model, human=human, subdir=subdir, commit=MENAGERIE_COMMIT,
                         upper=model.upper())
    return head + xml[xml.index(">") + 1:].lstrip("\n")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()

    failed = False
    for model, (subdir, human) in ARMS.items():
        source = resolve_source("mujoco_menagerie", MENAGERIE_URL, MENAGERIE_COMMIT,
                                sparse=subdir, subdir=subdir)
        xml = build(source, model, subdir, human)
        target = PKG / model / f"{model}.xml"

        if args.check:
            if not target.exists() or target.read_text() != xml:
                print(f"{target} differs from a fresh build - was it hand-edited?", file=sys.stderr)
                failed = True
            else:
                print(f"{target}: up to date with {MENAGERIE_COMMIT[:12]}")
            continue

        (target.parent / "meshes").mkdir(parents=True, exist_ok=True)
        for asset in sorted((source / "assets").iterdir()):
            if asset.suffix.lower() in (".stl", ".png", ".obj"):
                shutil.copy2(asset, target.parent / "meshes" / asset.name)
        shutil.copy2(source / "LICENSE", target.parent / f"{model.upper()}_LICENSE")
        target.write_text(xml)
        print(f"wrote {target} + meshes + {model.upper()}_LICENSE")
    return 1 if failed else 0


if __name__ == "__main__":
    raise SystemExit(main())
